/**
 * ============================================
 * META ADS LIBRARY (Tier 1)
 * ============================================
 * 모든 고객이 공통으로 사용하는 핵심 로직
 * 스크립트 라이브러리로 등록하여 재사용
 * ============================================
 */

/* ===== 공통 상수 ===== */
const TIMEZONE = "Asia/Seoul";
const GRAPH_VERSION = "v23.0";
const MAX_PAGES_TO_SCAN = 5;
const MAX_FORMS_PER_PAGE = 50;

/* ===== 재시도 설정 ===== */
const RETRY_MAX_ADS = 6;
const RETRY_BASE_DELAY_MS = 500;
const RETRY_JITTER_MS = 250;

/* ===== 시트 이름 상수 ===== */
const DEFAULT_ADS_LOG_SHEET = "meta_ads_log";
const DEFAULT_ADS_SHEET_NAME = "meta_ads";
const DEFAULT_LEADS_LOG_SHEET = "meta_leads_log";
const DEFAULT_LEADS_SHEET_NAME = "meta_instant_form_leads";
const DEFAULT_SETTINGS_SHEET = "setting_pages";
const DEFAULT_FORM_SETTINGS_SHEET = "setting_form";
const DEFAULT_CAMPAIGN_MAPPING_SHEET = "index";

/* ===== 매핑 키 상수 ===== */
const CAMPAIGN_MAP_KEYS = ["ad_category1", "ad_category2", "ad_category3"];

/**
 * ============================================
 * 시트 접근 유틸리티
 * ============================================
 */

/**
 * 시트 ID로 스프레드시트 열기
 */
function getSpreadsheetById(sheetId) {
  if (!sheetId) throw new Error("TARGET_SHEET_ID가 설정되지 않았습니다.");
  return SpreadsheetApp.openById(sheetId);
}

/**
 * 시트가 없으면 생성
 */
function getOrCreateSheet(ss, sheetName) {
  let sh = ss.getSheetByName(sheetName);
  if (!sh) sh = ss.insertSheet(sheetName);
  return sh;
}

/**
 * ============================================
 * 유틸리티 함수들
 * ============================================
 */

/**
 * 어제 날짜 반환 (YYYY-MM-DD)
 */
function getYesterday() {
  const now = new Date();
  now.setDate(now.getDate() - 1);
  return Utilities.formatDate(now, TIMEZONE, "yyyy-MM-dd");
}

/**
 * 날짜 포맷팅
 */
function formatYMD(d) {
  return Utilities.formatDate(d, TIMEZONE, "yyyy-MM-dd");
}

/**
 * 날짜 범위를 배열로 반환
 */
function enumerateDates(from, to) {
  const out = [];
  const s = new Date(from + "T00:00:00");
  const e = new Date(to + "T00:00:00");
  for (let d = new Date(s); d <= e; d.setDate(d.getDate() + 1)) {
    out.push(Utilities.formatDate(d, TIMEZONE, "yyyy-MM-dd"));
  }
  return out;
}

/**
 * 안전한 Alert (UI 없는 환경 대응)
 */
function safeAlert(msg) {
  try {
    SpreadsheetApp.getUi().alert(msg);
  } catch (e) {
    Logger.log(String(msg));
  }
}

/**
 * Sleep 래퍼
 */
function sleepMs(ms) {
  Utilities.sleep(ms);
}

/**
 * ============================================
 * 로깅 함수
 * ============================================
 */

/**
 * 로그 시트에 한 줄 추가
 */
function logLine(ss, logSheetName, status, message, extraObj) {
  try {
    const sh = getOrCreateSheet(ss, logSheetName);
    if (sh.getLastRow() === 0) {
      sh.appendRow(["ts", "status", "message", "json"]);
    }
    const ts = Utilities.formatDate(new Date(), TIMEZONE, "yyyy-MM-dd HH:mm:ss");
    const json = extraObj ? JSON.stringify(extraObj) : "";
    sh.appendRow([ts, status, String(message || ""), json]);
  } catch (e) {
    Logger.log("logLine failed: " + e);
  }
}

/**
 * ============================================
 * HTTP 유틸리티
 * ============================================
 */

/**
 * URL 쿼리스트링 빌드
 */
function buildUrl(base, obj) {
  const qs = Object.keys(obj)
    .map(k => `${encodeURIComponent(k)}=${encodeURIComponent(obj[k])}`)
    .join("&");
  return `${base}?${qs}`;
}

/**
 * 재시도 로직이 포함된 JSON fetch
 */
function fetchJson(url, params) {
  for (let attempt = 0; attempt <= RETRY_MAX_ADS; attempt++) {
    const res = UrlFetchApp.fetch(url, Object.assign({ muteHttpExceptions: true }, params || {}));
    const code = res.getResponseCode();
    const body = res.getContentText();

    if (code < 400) {
      try {
        return JSON.parse(body);
      } catch (e) {
        throw new Error("JSON parse error: " + e + "\n" + body);
      }
    }

    let isRateLimited = false;
    try {
      const err = JSON.parse(body).error || {};
      const msg = (err.message || "").toLowerCase();
      const ecode = err.code;
      if (
        ecode === 4 ||
        ecode === 613 ||
        msg.includes("bandwidth") ||
        msg.includes("reduce the amount") ||
        msg.includes("user request limit")
      ) {
        isRateLimited = true;
      }
    } catch (e) {}

    if (isRateLimited && attempt < RETRY_MAX_ADS) {
      const wait = RETRY_BASE_DELAY_MS * Math.pow(2, attempt) + Math.floor(Math.random() * RETRY_JITTER_MS);
      sleepMs(wait);
      continue;
    }

    throw new Error(`HTTP ${code} ${url}\n${body}`);
  }
  throw new Error("fetchJson unexpected fall-through");
}

/**
 * ============================================
 * Meta API - Ads Insights
 * ============================================
 */

/**
 * 광고 계정의 Insights 데이터 조회
 */
function fetchDailyBreakdown(accessToken, actId, fromDate, toDate) {
  const url = `https://graph.facebook.com/${GRAPH_VERSION}/${encodeURIComponent(actId)}/insights`;
  const params = { method: "get", muteHttpExceptions: true };
  const query = {
    access_token: accessToken,
    time_range: JSON.stringify({ since: fromDate, until: toDate }),
    time_increment: 1,
    level: "campaign",
    fields: [
      "date_start", 
      "date_stop",
      "account_id", 
      "account_name", 
      "account_currency", 
      "spend",
      "campaign_name",
      "objective", 
      "optimization_goal",
      "impressions", 
      "reach",
      "clicks", 
      "inline_link_clicks", 
      "unique_clicks", 
      "unique_inline_link_clicks",
      "ctr", 
      "unique_ctr", 
      "inline_link_click_ctr",
      "cpc", 
      "cpm", 
      "cpp", 
      "cost_per_inline_link_click",
      "actions"
    ].join(","),
    // breakdowns: "publisher_platform",
    action_breakdowns: "action_type",
  };

  let next = buildUrl(url, query);
  const results = [];
  let safety = 0;

  while (next && safety++ < 50) {
    const json = fetchJson(next, params);
    if (Array.isArray(json.data)) results.push(...json.data);
    next = json.paging && json.paging.next ? json.paging.next : null;
    Utilities.sleep(600); // 레이트리밋 방지
  }

  return results;
}

/**
 * ============================================
 * 액션 합산 로직
 * ============================================
 */

function normActionType(s) {
  return (s || "").toString().trim().toLowerCase();
}

function sumByTypes(actions, typesArr) {
  if (!Array.isArray(actions)) return 0;
  const want = new Set(typesArr.map(s => s.toLowerCase()));
  let s = 0;
  for (const a of actions) {
    const type = String(a.action_type || "").toLowerCase();
    if (want.has(type)) s += Number(a.value || 0);
  }
  return s;
}

function sumLinkClicks(actions) {
  const LINK_CLICK_CANDIDATES = [
    "link_click", 
    "click", 
    "outbound_click", 
    "onsite_conversion.messaging_link_click"
  ];
  return sumByTypes(actions, LINK_CLICK_CANDIDATES);
}

function sumLandingPageViews(actions) {
  const LANDING_PAGE_VIEW_CANDIDATES = [
    "landing_page_view",
    "offsite_conversion.fb_pixel_landing_page_view"
  ];
  return sumByTypes(actions, LANDING_PAGE_VIEW_CANDIDATES);
}

function sumLeads(actions) {
  const LEAD_CANDIDATES = [
    "lead",
    "offsite_conversion.fb_pixel_lead",
    "omni_complete_registration"
  ];
  return sumByTypes(actions, LEAD_CANDIDATES);
}

function sumCompleteRegistrations(actions) {
  const COMPLETE_REGISTRATION_CANDIDATES = [
    "complete_registration",
    "offsite_conversion.fb_pixel_complete_registration",
    "omni_complete_registration"
  ];
  return sumByTypes(actions, COMPLETE_REGISTRATION_CANDIDATES);
}

function sumContacts(actions) {
  const CONTACT_CANDIDATES = [
    "contact",
    "offsite_conversion.fb_pixel_contact"
  ];
  return sumByTypes(actions, CONTACT_CANDIDATES);
}

function sumMessageStarted(actions) {
  const MESSAGE_STARTED_CANDIDATES = [
    "onsite_conversion.messaging_conversation_started_7d"
  ];
  return sumByTypes(actions, MESSAGE_STARTED_CANDIDATES);
}

/**
 * ============================================
 * 목표 정규화
 * ============================================
 */

function normalizeGoal(objective, optimization_goal) {
  const obj = (objective || "").toUpperCase();
  const opt = (optimization_goal || "").toUpperCase();
  if (obj.includes("ENGAGEMENT") || opt.includes("CONVERSATIONS")) {
    return "OUTCOME_ENGAGEMENT";
  }
  return obj || opt || "";
}

/**
 * ============================================
 * 메인 로직: Ads Insights 데이터 수집
 * ============================================
 */

/**
 * 광고 데이터 수집 및 시트 저장
 * @param {Object} config - 고객 설정 객체
 * @param {string} since - 시작일 (YYYY-MM-DD)
 * @param {string} until - 종료일 (YYYY-MM-DD)
 * @param {boolean} headless - true면 alert 대신 로그만
 */
function fetchMetaInsightsWithRange(config, since, until, headless = false) {
  const runId = `${since}_${until}_${Date.now()}`;
  const startAt = new Date();

  const ss = getSpreadsheetById(config.TARGET_SHEET_ID);
  const sh = getOrCreateSheet(ss, config.ADS_SHEET_NAME || DEFAULT_ADS_SHEET_NAME);
  const logSheetName = config.ADS_LOG_SHEET || DEFAULT_ADS_LOG_SHEET;

  logLine(ss, logSheetName, "START", `fetchMetaInsights start ${runId}`, {
    since,
    until,
    accounts: config.AD_ACCOUNT_IDS.length
  });

  try {
    const headers = [
      "ad_date",
      "ad_account",
      "ad_account_name",
      "campaign_name",
      // "platform",
      "goal",
      "impressions",
      "reach",
      "clicks",
      "link_clicks", 
      // "inline_link_clicks", 
      "unique_clicks", 
      // "unique_inline_link_clicks",
      "ctr", 
      "unique_ctr", 
      // "inline_link_click_ctr",
      "cpc", 
      "cpm", 
      // "cpp", 
      // "cost_per_inline_link_click",
      "landing_page_views",
      "leads",
      "complete_registrations", 
      "contacts",
      "message_started",
      "expense",
      "currency",
      "report_from",
      "report_to"
    ];

    if (sh.getLastRow() === 0) sh.appendRow(headers);

    const dateRanges = enumerateDates(since, until);
    const out = [];

    for (const actId of config.AD_ACCOUNT_IDS) {
      for (const d of dateRanges) {
        const rows = fetchDailyBreakdown(config.USER_LONG_TERM_ACCESS_TOKEN_CONST, actId, d, d);

        for (const row of rows) {
          const {
            date_start, 
            account_currency, 
            account_name, 
            spend,
            campaign_name, 
            objective, 
            optimization_goal,
            // publisher_platform, 
            actions,
            impressions, 
            reach,
            clicks, 
            inline_link_clicks, 
            unique_clicks, 
            unique_inline_link_clicks,
            ctr, 
            unique_ctr, 
            inline_link_click_ctr,
            cpc, 
            cpm, 
            cpp, 
            cost_per_inline_link_click
          } = row;



          const linkClicks = sumLinkClicks(actions);
          const landingPageViews = sumLandingPageViews(actions);
          const leads = sumLeads(actions);
          const completeRegistrations = sumCompleteRegistrations(actions);  
          const contacts = sumContacts(actions);
          const messageStarted = sumMessageStarted(actions);
          const goal = normalizeGoal(objective, optimization_goal);
          const expense = Number(spend || 0);

          out.push([
            date_start,
            actId.replace("act_", ""),
            account_name || "",
            campaign_name || "",
            // (publisher_platform || "").toLowerCase(),
            goal,
            Number(impressions || 0),
            Number(reach || 0),
            Number(clicks || 0),
            Number(linkClicks || 0),
            // Number(inline_link_clicks || 0),
            Number(unique_clicks || 0),
            // Number(unique_inline_link_clicks || 0),
            Number(ctr || 0),
            Number(unique_ctr || 0),
            // Number(inline_link_click_ctr || 0),
            Number(cpc || 0),
            Number(cpm || 0),
            // Number(cpp || 0),
            // Number(cost_per_inline_link_click || 0),
            Number(landingPageViews || 0),
            Number(leads || 0),
            Number(completeRegistrations || 0),
            Number(contacts || 0),
            Number(messageStarted || 0),
            expense,
            account_currency || "",
            d, 
            d
          ]);
        }
      }
    }

    if (out.length) {
      sh.getRange(sh.getLastRow() + 1, 1, out.length, out[0].length).setValues(out);
    }

    const doneMsg = `✅ 완료: ${out.length.toLocaleString()}행 적재 (기간: ${since} ~ ${until})`;
    if (headless) Logger.log(doneMsg); else safeAlert(doneMsg);

    logLine(ss, logSheetName, "DONE", `fetchMetaInsights done ${runId}`, {
      rows: out.length,
      ms: (new Date() - startAt)
    });

    return { success: true, rows: out.length };

  } catch (err) {
    const msg = "❌ 실패: " + (err && err.message ? err.message : err);
    Logger.log(msg);
    logLine(ss, logSheetName, "ERROR", `fetchMetaInsights error ${runId}`, {
      msg,
      stack: String(err && err.stack || "")
    });
    if (!headless) safeAlert(msg);
    throw err;
  }
}

/**
 * ============================================
 * 캠페인 매핑 로직
 * ============================================
 */

function normKey(s) {
  if (s == null) return "";
  return String(s).trim().toLowerCase();
}

function idxMap(headers) {
  const m = {};
  headers.forEach((h, i) => {
    if (h) m[h] = i;
  });
  return m;
}

/**
 * campaign_name을 기준으로 index 시트의 값을 매핑
 */
function mapPageMetaByCampaignName(config) {
  const ss = getSpreadsheetById(config.TARGET_SHEET_ID);
  const mappingSheetName = config.CAMPAIGN_MAPPING_SHEET || DEFAULT_CAMPAIGN_MAPPING_SHEET;
  const adsSheetName = config.ADS_SHEET_NAME || DEFAULT_ADS_SHEET_NAME;

  // 1) 매핑 시트 읽기
  const mapSh = ss.getSheetByName(mappingSheetName);
  if (!mapSh) throw new Error(`시트를 찾을 수 없습니다: ${mappingSheetName}`);

  const mapLastRow = mapSh.getLastRow();
  const mapLastCol = mapSh.getLastColumn();
  if (mapLastRow < 2 || mapLastCol < 2) throw new Error(`${mappingSheetName} 시트에 데이터가 없습니다.`);

  const mapValues = mapSh.getRange(1, 1, mapLastRow, mapLastCol).getValues();
  const mapHeader = mapValues[0].map(h => String(h || "").trim());
  const hIdx = idxMap(mapHeader);

  const required = ["campaign_name"].concat(CAMPAIGN_MAP_KEYS);
  const miss = required.filter(k => !(k in hIdx));
  if (miss.length) throw new Error(`${mappingSheetName} 헤더 누락: ${miss.join(", ")}`);

  const mapping = new Map();
  for (let r = 1; r < mapValues.length; r++) {
    const row = mapValues[r];
    const key = normKey(row[hIdx["campaign_name"]]);
    if (!key) continue;
    const obj = {};
    for (const k of CAMPAIGN_MAP_KEYS) obj[k] = row[hIdx[k]] ?? "";
    mapping.set(key, obj);
  }

  // 2) 대상 시트 준비
  const targetSh = ss.getSheetByName(adsSheetName);
  if (!targetSh) throw new Error(`시트를 찾을 수 없습니다: ${adsSheetName}`);
  if (targetSh.getLastRow() === 0) {
    throw new Error(`${adsSheetName} 시트에 데이터가 없습니다.`);
  }

  const tgtLastRow = targetSh.getLastRow();
  const tgtLastCol = targetSh.getLastColumn();
  const tgtHeader = targetSh.getRange(1, 1, 1, tgtLastCol).getValues()[0].map(h => String(h || "").trim());
  let tIdx = idxMap(tgtHeader);

  if (!("campaign_name" in tIdx)) {
    throw new Error(`${adsSheetName} 헤더에 'campaign_name' 컬럼이 없습니다.`);
  }
  const pageNameCol = tIdx["campaign_name"] + 1;

  // 없는 컬럼 추가
  const newHeadersToAppend = [];
  for (const k of CAMPAIGN_MAP_KEYS) {
    if (!(k in tIdx)) newHeadersToAppend.push(k);
  }
  if (newHeadersToAppend.length) {
    targetSh.getRange(1, tgtLastCol + 1, 1, newHeadersToAppend.length).setValues([newHeadersToAppend]);
  }

  // 최신 헤더 재계산
  const newLastCol = targetSh.getLastColumn();
  const freshHeader = targetSh.getRange(1, 1, 1, newLastCol).getValues()[0].map(h => String(h || "").trim());
  tIdx = idxMap(freshHeader);

  // 3) campaign_name 값 읽기
  const pageVals = targetSh.getRange(2, pageNameCol, tgtLastRow - 1, 1).getValues().map(v => v[0]);

  // 4) 각 매핑 컬럼에 값 채우기
  const updatedCols = [];
  for (const k of CAMPAIGN_MAP_KEYS) {
    const colIdx1 = tIdx[k] + 1;
    const outCol = new Array(tgtLastRow - 1);
    for (let i = 0; i < pageVals.length; i++) {
      const key = normKey(pageVals[i]);
      const m = key ? mapping.get(key) : null;
      outCol[i] = m ? (m[k] ?? "") : "";
    }
    targetSh.getRange(2, colIdx1, tgtLastRow - 1, 1).setValues(outCol.map(v => [v]));
    updatedCols.push(k);
  }

  return { rows: tgtLastRow - 1, updatedCols };
}
